Feature: Resource Status Linking

Scenario: Unsupported Resource Type Handling

Given a Resource is added via Resource Lookup
And the Resource type is unsupported
When the Resource is linked to the Resource module
Then an error message is displayed
And the Resource is not linked

Python:

from behave import given, when, then

@given('a Resource is added via Resource Lookup')
def step_given_resource_added(context):
    context.resource_added = True

@given('the Resource type is unsupported')
def step_given_unsupported_resource_type(context):
    context.resource_type = 'unsupported'

@when('the Resource is linked to the Resource module')
def step_when_resource_linked(context):
    context.link_attempted = True

@then('an error message is displayed')
def step_then_error_message_displayed(context):
    assert context.link_attempted and context.resource_type == 'unsupported'

@then('the Resource is not linked')
def step_then_resource_not_linked(context):
    assert not context.resource_linked

